handleAddValueAdd({ key, newValue }: any) {
    const { data, keyPath = [], nextDeep: deep } = this.state;
    const { beforeAddAction, logger } = this.props;

    (beforeAddAction || Promise.resolve.bind(Promise))(key, keyPath, deep, newValue)
      .then(() => {
        // Update data
        data[key] = newValue;
        this.setState({
          data,
        });
        // Cancel add to close
